def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']
    # Use exponential decay weighting for more recent actions
    weight = 0.75 ** round_num
    if action == 'cooperate':
        delta = 0.5 * weight
    else:
        delta = -0.5 * weight
    new_reputation = current_reputation + delta
    new_reputation = max(-1.0, min(1.0, new_reputation))
    return new_reputation

